import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import { Box, Button, IconButton, Stack, Tooltip, Typography } from "@mui/material";
import Link from "next/link";
import PremiumDataTable, { PremiumDataTableColumn } from "@/components/common/PremiumDataTable";
import dicConstant from "@/constants/Constant.json";

const employees = [
  { id: "E001", name: "Ava Johnson", department: "Engineering", role: "Frontend Developer" },
  { id: "E002", name: "Liam Smith", department: "HR", role: "HR Executive" },
  { id: "E003", name: "Noah Davis", department: "Finance", role: "Accountant" }
];

type EmployeeRow = {
  id: string;
  name: string;
  department: string;
  role: string;
};

export default function EmployeesPage() {
  const columns: PremiumDataTableColumn<EmployeeRow>[] = [
    {
      field: "id",
      headerName: dicConstant.employees.grid.id,
      getSortValue: (dicRow) => dicRow.id,
      getFilterValue: (dicRow) => dicRow.id,
      renderCell: (dicRow) => <Typography sx={{ color: "#94a3b8", fontWeight: 500 }}>{dicRow.id}</Typography>
    },
    {
      field: "name",
      headerName: dicConstant.employees.grid.name,
      getSortValue: (dicRow) => dicRow.name,
      getFilterValue: (dicRow) => dicRow.name,
      renderCell: (dicRow) => <Typography sx={{ color: "#0f172a", fontWeight: 600 }}>{dicRow.name}</Typography>
    },
    {
      field: "department",
      headerName: dicConstant.employees.grid.department,
      getSortValue: (dicRow) => dicRow.department,
      getFilterValue: (dicRow) => dicRow.department,
      renderCell: (dicRow) => <Typography sx={{ color: "#64748b" }}>{dicRow.department}</Typography>
    },
    {
      field: "role",
      headerName: dicConstant.employees.grid.role,
      getSortValue: (dicRow) => dicRow.role,
      getFilterValue: (dicRow) => dicRow.role,
      renderCell: (dicRow) => <Typography sx={{ color: "#64748b" }}>{dicRow.role}</Typography>
    },
    {
      field: "id",
      headerName: dicConstant.employees.grid.action,
      sortable: false,
      filterable: false,
      exportable: false,
      align: "center",
      renderCell: (dicRow) => (
        <Tooltip title="View details" arrow>
          <IconButton
            component={Link}
            href={`/employees/${dicRow.id}`}
            aria-label="View details"
            size="small"
            sx={{
              width: 34,
              height: 34,
              transition: "all 0.2s ease",
              "&:hover": { backgroundColor: "rgba(37,99,235,0.08)" }
            }}
          >
            <VisibilityOutlinedIcon sx={{ fontSize: 20, color: "#475569" }} />
          </IconButton>
        </Tooltip>
      )
    }
  ];

  return (
    <Stack
      spacing={4}
      sx={{
        animation: "employeesFadeIn 200ms ease-out",
        "@keyframes employeesFadeIn": {
          from: { opacity: 0, transform: "translateY(8px)" },
          to: { opacity: 1, transform: "translateY(0)" }
        }
      }}
    >
      <Box>
        <Typography sx={{ fontSize: { xs: 30, md: 34 }, fontWeight: 700, lineHeight: 1.15 }}>
          {dicConstant.employees.pageTitle}
        </Typography>
        <Typography sx={{ color: "#64748b", mt: 1 }}>Manage and monitor your workforce.</Typography>
      </Box>

      <Button
        variant="contained"
        href="/employees/new"
        sx={{
          alignSelf: "flex-start",
          height: 48,
          px: 2.5,
          borderRadius: "14px",
          backgroundColor: "#2563eb",
          boxShadow: "0 6px 16px rgba(37,99,235,0.35)",
          transition: "all 0.15s ease",
          "&:hover": {
            transform: "translateY(-1px)",
            backgroundColor: "#1d4ed8"
          }
        }}
      >
        {dicConstant.employees.addButton}
      </Button>

      <PremiumDataTable
        columns={columns}
        rows={employees}
        rowIdField="id"
        showExportOptions
        exportFileName="employees-list"
      />
    </Stack>
  );
}
